<?php
if(!function_exists('esc')){http_response_code(404);exit;}
require_once dirname(__DIR__,2).'/app/ContactPhone.php';
function contactPhoneField(string $name,string $label,string $value=''):void {
 $digits=preg_replace('/\D/','',$value);$co=str_starts_with($digits,'57')&&strlen($digits)===12;$fixed=$co&&str_starts_with(substr($digits,2),'60');$country=$co?'57':(str_starts_with($digits,'1')&&strlen($digits)===11?'1':'57');$national=$co?substr($digits,$fixed?5:2):($country==='1'?substr($digits,1):$digits);
 $type=(string)($_POST[$name.'_kind']??($fixed?'fixed':'mobile'));$area=(string)($_POST[$name.'_area']??($fixed?substr($digits,2,3):'604'));$country=(string)($_POST[$name.'_country_code']??$country);$national=(string)($_POST[$name.'_national']??$national);
 ?><fieldset class="contact-phone-fields wide" data-contact-phone data-phone-name="<?=esc($name)?>"><legend><?=esc($label)?></legend><div class="contact-phone-types"><?php foreach(['mobile'=>'Celular','fixed'=>'Teléfono fijo'] as $kind=>$text):?><label><input type="radio" name="<?=esc($name)?>_kind" value="<?=$kind?>" <?=$type===$kind?'checked':''?>> <?=$text?></label><?php endforeach ?></div><div class="contact-phone-row"><label>Código de país<span class="contact-phone-prefix">+<input name="<?=esc($name)?>_country_code" inputmode="numeric" maxlength="3" pattern="[1-9][0-9]{0,2}" value="<?=esc($country)?>" aria-label="Código de país del teléfono"></span></label><label data-contact-area <?=$type!=='fixed'||$country!=='57'?'hidden':''?>>Indicativo regional<select name="<?=esc($name)?>_area"><?php foreach(BusinessPhone::AREAS as $code=>$region):?><option value="<?=$code?>" <?=$area===(string)$code?'selected':''?>><?=$code?> · <?=esc($region)?></option><?php endforeach ?></select></label><label data-contact-foreign-area <?=$type!=='fixed'||$country==='57'?'hidden':''?>>Indicativo regional<input name="<?=esc($name)?>_foreign_area" inputmode="numeric" maxlength="5" value="<?=esc($_POST[$name.'_foreign_area']??'')?>"></label><label>Número<input type="tel" name="<?=esc($name)?>_national" inputmode="tel" autocomplete="tel-national" maxlength="24" value="<?=esc($national)?>"></label></div><input type="hidden" name="<?=esc($name)?>" value="<?=esc($value)?>"><small data-contact-preview aria-live="polite"></small></fieldset><?php
}
